def transform(grid):
    from itertools import permutations

    h, w = len(grid), len(grid[0])
    frames = []
    frame_cells = set()

    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue

        border = all(
            grid[r][c] == color
            for r in range(r0, r1 + 1)
            for c in range(c0, c1 + 1)
            if r in (r0, r1) or c in (c0, c1)
        )
        if border:
            frames.append((color, r0, r1, c0, c1))
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if r in (r0, r1) or c in (c0, c1):
                        frame_cells.add((r, c))

    counts = {}
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value and (r, c) not in frame_cells:
                counts[value] = counts.get(value, 0) + 1

    candidates = list(counts)
    best_assignment = None
    best_cost = float("inf")

    if len(candidates) >= len(frames):
        for assignment in permutations(candidates, len(frames)):
            cost = 0
            for (_, r0, r1, c0, c1), marker in zip(frames, assignment):
                target = sum(
                    1 for r in range(r0 + 1, r1)
                    for c in range(c0 + 1, c1)
                    if (r + c) % 2 == (r0 + c0) % 2
                )
                cost += abs(counts[marker] - target)
            if cost < best_cost:
                best_cost = cost
                best_assignment = assignment

    out = [[0] * w for _ in range(h)]
    for i, (color, r0, r1, c0, c1) in enumerate(frames):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color

        if best_assignment:
            marker = best_assignment[i]
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r + c) % 2 == (r0 + c0) % 2:
                        out[r][c] = marker

    return out
